-- =====================================================================
--  Workspace -> monitor assignment
-- ---------------------------------------------------------------------
--  Originally generated by nwg-displays as ten near-identical blocks.
--  Rules 1-8 live on the laptop panel (eDP-1), 9-10 on the external 4K
--  (HDMI-A-1). Workspace 1 and 9 are the per-monitor defaults.
-- =====================================================================

local LG = "eDP-1"
local EXT = "HDMI-A-1"
local LG_WORKSPACES = 8

for ws = 1, LG_WORKSPACES + 2 do
	local rule = {
		workspace = tostring(ws),
		monitor = ws <= LG_WORKSPACES and LG or EXT,
	}
	if ws == 1 then
		rule.default = true
		rule.layout = "dwindle"
	elseif ws == 9 then
		rule.default = true
	end
	hl.workspace_rule(rule)
end
